  const activity = getActivity(member.id);

  return (
    <Container component="main" maxWidth="md" sx={{ py: { xs: 3, md: 5 } }}>
      <Breadcrumbs aria-label="Breadcrumb" sx={{ mb: 3 }}>
        <MuiLink component={Link} href="/" underline="hover" color="inherit">
          Team
        </MuiLink>
        <Typography color="text.primary">{member.name}</Typography>
      </Breadcrumbs>

      <Paper variant="outlined" sx={{ p: { xs: 2, sm: 3 }, mb: 3 }}>
        <Stack
          direction={{ xs: "column", sm: "row" }}
          spacing={3}
          sx={{ alignItems: { sm: "center" } }}
        >
          <MemberAvatar id={member.id} name={member.name} size={80} />
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="h4" component="h1" sx={{ fontWeight: 700 }}>
              {member.name}
            </Typography>
            <Typography color="text.secondary" sx={{ overflowWrap: "anywhere" }}>
              {member.email}
            </Typography>
            <Stack direction="row" spacing={1} sx={{ mt: 1.5 }}>
              <RoleBadge role={member.role} />
              <StatusBadge status={member.status} />
            </Stack>
          </Box>
        </Stack>

        <Divider sx={{ my: 3 }} />

        <Box
          component="dl"
          sx={{
            m: 0,
            display: "grid",
            gap: 2,
            gridTemplateColumns: { xs: "1fr", sm: "repeat(3, 1fr)" },
          }}
        >
          <Field label="Role">
            <Typography>{member.role}</Typography>
          </Field>
          <Field label="Status">
            <Typography>{member.status}</Typography>
          </Field>
          <Field label="Joined">
            <Typography>{formatDate(member.joined)}</Typography>
          </Field>
        </Box>
      </Paper>

      <Paper variant="outlined" sx={{ p: { xs: 2, sm: 3 } }}>
        <Typography variant="h6" component="h2" sx={{ fontWeight: 600 }}>
          Recent activity
        </Typography>
        {activity.length === 0 ? (
          <Typography color="text.secondary" sx={{ mt: 1 }}>
            {member.status === "Invited"
              ? `${member.name} hasn't accepted the invitation yet, so there is no activity to show.`
              : "No recent activity."}
          </Typography>
        ) : (
          <List disablePadding sx={{ mt: 1 }}>
            {activity.map((item, index) => (
              <React.Fragment key={item.id}>
                {index > 0 && <Divider component="li" />}
                <ListItem disableGutters>
                  <ListItemText
                    primary={
                      <>
                        {item.action}{" "}
                        <Box component="span" sx={{ fontWeight: 600 }}>
                          {item.target}
                        </Box>
                      </>
                    }
                    secondary={item.when}
                  />
                </ListItem>
              </React.Fragment>
            ))}
          </List>
        )}
      </Paper>
    </Container>
  );
}
